  ('arctan 1 + arctan(−1) toplamı kaçtır?', '0', ['π/2', 'π', '−π/2'], 'arctan tek fonksiyondur: π/4 + (−π/4) = 0.'),
  ('arcsin x ifadesinin tanımlı olması için x hangi aralıkta olmalıdır?', '[−1, 1]', ['(−1, 1)', '[0, 1]', '[−π/2, π/2]'], 'arcsin, sinüsün değerlerini girdi olarak aldığından tanım kümesi [−1, 1]\'dir.'),
  ('tan(arccos(−5/13)) değeri kaçtır?', '−12/5', ['12/5', '−5/12', '12/13'], 'θ = arccos(−5/13) ikinci bölgededir; sin θ = 12/13 ve tan θ = −12/5.'),
  ('cos(a + b) açılımı aşağıdakilerden hangisidir?', 'cos a·cos b − sin a·sin b', ['cos a·cos b + sin a·sin b', 'sin a·cos b + cos a·sin b', 'cos a·sin b − sin a·cos b'], 'Toplam formülünde kosinüs açılımı kosinüslerin çarpımından sinüslerin çarpımı çıkarılarak yazılır.'),
  ('tan 105° değeri aşağıdakilerden hangisidir?', '−2 − √3', ['2 + √3', '2 − √3', '−2 + √3'], 'tan(60° + 45°) = (√3 + 1)/(1 − √3) = −(2 + √3).'),
  ('(tan 25° + tan 20°)/(1 − tan 25°·tan 20°) oranı kaça eşittir?', '1', ['√3', 'tan 5°', '1/2'], 'Bu ifade tan(25° + 20°) = tan 45° = 1\'in açılımıdır.'),
  ('cos 2x ifadesinin yalnız kosinüs cinsinden yazılışı hangisidir?', '2cos²x − 1', ['1 − 2cos²x', '2cos x − 1', 'cos²x − 1'], 'cos 2x = cos²x − sin²x = cos²x − (1 − cos²x) = 2cos²x − 1.'),
  ('2 sin 22,5°·cos 22,5° çarpımının değeri kaçtır?', '√2/2', ['1/2', '√3/2', '1'], 'İki kat açı formülüne göre ifade sin 45° = √2/2\'ye eşittir.'),
  ('cos²15° − sin²15° farkı aşağıdakilerden hangisidir?', '√3/2', ['1/2', '1', '√2/2'], 'İfade cos(2·15°) = cos 30° = √3/2 olur.'),
  ('cos x = 1/4 ise cos 2x değeri nedir?', '−7/8', ['1/2', '7/8', '−15/16'], 'cos 2x = 2cos²x − 1 = 2/16 − 1 = −7/8.'),
  ('1 − 2sin²(3x) farkı tek bir trigonometrik terim olarak yazılırsa hangisi bulunur?', 'cos 6x', ['cos 3x', 'sin 6x', 'cos²3x'], '1 − 2sin²θ = cos 2θ; θ = 3x için cos 6x elde edilir.'),
  ('sin 2x/(1 + cos 2x) ifadesi sadeleştirildiğinde ne olur?', 'tan x', ['cot x', 'sin x', '2 tan x'], 'Pay 2 sin x cos x, payda 2cos²x olur; oran sin x/cos x = tan x.'),
  ('sin x + cos x = 1/5 ise sin 2x değeri kaçtır?', '−24/25', ['24/25', '1/25', '−1/25'], 'Kare alınırsa 1 + sin 2x = 1/25 ⇒ sin 2x = −24/25.'),
  ('tan x = 2 iken sin 2x değerini tanjant cinsinden formülle bulunuz.', '4/5', ['4/3', '−4/3', '2/5'], 'sin 2x = 2tan x/(1 + tan²x) = 4/5.'),
  ('tan x = 2 iken cos 2x değeri nedir?', '−3/5', ['3/5', '−4/3', '−3/25'], 'cos 2x = (1 − tan²x)/(1 + tan²x) = (1 − 4)/(1 + 4) = −3/5.'),
  ('cos⁴x − sin⁴x ifadesi tek bir kosinüs terimiyle nasıl yazılır?', 'cos 2x', ['cos 4x', '1', 'cos 2x + sin 2x'], '(cos²x − sin²x)(cos²x + sin²x) = cos 2x · 1 = cos 2x.'),
  ('sin 3x ifadesinin yalnız sin x cinsinden açılımı hangisidir?', '3 sin x − 4 sin³x', ['4 sin³x − 3 sin x', '3 sin x + 4 sin³x', '3 sin x − sin³x'], 'sin(2x + x) açılıp cos²x = 1 − sin²x yazılırsa 3 sin x − 4 sin³x elde edilir.'),
  ('cos 3x için kosinüs cinsinden doğru formül hangisidir?', '4cos³x − 3cos x', ['3cos x − 4cos³x', '4cos³x + 3cos x', 'cos³x − 3cos x'], 'cos(2x + x) açılımı ve sin²x = 1 − cos²x dönüşümüyle 4cos³x − 3cos x bulunur.'),
  ('Sinüsü 1/3 olan bir açının üç katının sinüsünü üç kat açı formülüyle hesaplayınız.', '23/27', ['1', '1/27', '−23/27'], '3·(1/3) − 4·(1/27) = 1 − 4/27 = 23/27.'),
  ('Ölçüleri 75° ve 15° olan iki açının sinüsleri toplanırsa, dönüşüm formülüyle hangi sonuç elde edilir?', '√6/2', ['√2/2', '√6/4', '√3/2'], '2 sin 45°·cos 30° = 2·(√2/2)(√3/2) = √6/2.'),
  ('(sin 5x + sin 3x)/(cos 5x + cos 3x) ifadesinin sade biçimi hangisidir?', 'tan 4x', ['tan x', 'cot 4x', 'tan 8x'], 'Pay 2 sin 4x cos x, payda 2 cos 4x cos x olur; oran tan 4x.'),
  ('cos 20° + cos 100° + cos 140° toplamının değeri kaçtır?', '0', ['1/2', '−1/2', 'cos 20°'], 'cos 100° + cos 140° = 2 cos 120° cos 20° = −cos 20°; toplam 0.'),
  ('sin x + √3 cos x ifadesi R·sin(x + φ) biçiminde yazılırsa R ve φ ne olur?', 'R = 2, φ = π/3', ['R = 2, φ = π/6', 'R = √3, φ = π/3', 'R = 4, φ = π/3'], 'R = √(1 + 3) = 2; cos φ = 1/2, sin φ = √3/2 ⇒ φ = π/3.'),
  ('sin x + cos x toplamı √2·sin(x + α) biçiminde yazıldığında α kaç derecedir?', '45°', ['30°', '60°', '22,5°'], '√2 sin(x + 45°) = √2(sin x·√2/2 + cos x·√2/2) = sin x + cos x.'),
  ('sin x = 1 denkleminin genel çözümü hangisidir (k ∈ ℤ)?', 'x = π/2 + 2kπ', ['x = π/2 + kπ', 'x = kπ', 'x = 2kπ'], 'Sinüs yalnız birim çemberin en üst noktasında 1 değerini alır; bu nokta her 2π\'de bir tekrar eder.'),
  ('sin x = a denkleminin bir çözümü α ise bütün çözümler (k ∈ ℤ) nasıl yazılır?', 'x = α + 2kπ veya x = π − α + 2kπ', ['x = ±α + 2kπ', 'x = α + kπ', 'x = α + 2kπ veya x = −α + 2kπ'], 'Sinüsü eşit açılar ya aynı bitiş kenarındadır ya da birbirinin bütünleridir.'),
  ('İki kat açının sinüsü √3/2 olacak biçimde, dar açı olan x değerlerini belirleyiniz: sin 2x = √3/2.', 'π/6 ve π/3', ['π/3 ve 2π/3', 'π/6 ve π/4', 'π/12 ve π/6'], '2x ∈ (0, π) için 2x = π/3 veya 2π/3 ⇒ x = π/6 veya π/3.'),
  ('cos x = 0 denkleminin bütün çözümleri hangi biçimde yazılır (k ∈ ℤ)?', 'x = π/2 + kπ', ['x = kπ', 'x = 2kπ', 'x = π/2 + 2kπ'], 'Kosinüs birim çemberde (0, 1) ve (0, −1) noktalarında sıfırdır; bunlar π aralıkla tekrar eder.'),
  ('tan x = −1 denkleminin [0, 2π) aralığındaki çözümleri hangileridir?', '3π/4 ve 7π/4', ['π/4 ve 5π/4', '3π/4 ve 5π/4', '5π/4 ve 7π/4'], 'Tanjant II. ve IV. bölgelerde negatiftir; referans açı π/4\'tür.'),
  ('tan²x = 3 eşitliğini sağlayan ve 0 ile π arasında kalan açılar hangileridir?', 'π/3 ve 2π/3', ['π/6 ve 5π/6', 'π/3 ve 4π/3', 'π/6 ve π/3'], 'tan x = ±√3 ⇒ (0, π) aralığında π/3 ve 2π/3 bulunur.'),
  ('tan x + cot x = 2 denklemini sağlayan (0, π/2) aralığındaki x nedir?', 'π/4', ['π/3', 'π/6', '3π/8'], 'tan x = t ise t + 1/t = 2 ⇒ t² − 2t + 1 = 0 ⇒ t = 1 ⇒ x = π/4.'),
  ('Bir ABC üçgeninde a, b, c sırasıyla A, B, C köşelerinin karşısındaki kenarlar ise sinüs teoremi hangi eşitliği ifade eder?', 'a/sin A = b/sin B = c/sin C', ['a·sin A = b·sin B = c·sin C', 'a/cos A = b/cos B = c/cos C', 'a² = b² + c² − 2bc·cos A'], 'Sinüs teoremine göre her kenarın karşı açısının sinüsüne oranı sabittir (2R).'),
  ('Kosinüs teoremine göre ABC üçgeninde a² hangi ifadeye eşittir?', 'b² + c² − 2bc·cos A', ['b² + c² + 2bc·cos A', 'b² − c² − 2bc·cos A', 'b² + c² − bc·sin A'], 'a² = b² + c² − 2bc cos A; A dik olduğunda Pisagor bağıntısına indirgenir.'),
  ('İki kenarı b ve c, aralarındaki açısı A olan üçgenin alanını veren formül hangisidir?', '(1/2)·b·c·sin A', ['b·c·sin A', '(1/2)·b·c·cos A', '(1/2)·b·c·tan A'], 'Yükseklik c·sin A olduğundan alan (1/2)·b·(c sin A) bulunur.'),
  ('Kenarları 13, 14 ve 15 cm olan üçgenin alanı 84 cm²\'dir. Çevrel çemberinin yarıçapı kaç cm\'dir?', '65/8', ['7', '15/2', '65/16'], 'R = abc/(4·Alan) = 13·14·15/(4·84) = 2730/336 = 65/8 cm.'),
  ('Gözlemcinin yatay bakış doğrultusu ile kendisinden daha aşağıdaki bir cisme bakış doğrultusu arasındaki açıya ne ad verilir?', 'Alçalma açısı', ['Yükselme açısı', 'Eğim açısı', 'Sapma açısı'], 'Aşağıdaki cisimlere bakışta yatayla yapılan açı alçalma (depresyon) açısıdır.'),
  ('Bir gemi limandan kuzeydoğu yönünde (kuzeyle 45° açı) 20√2 km gidiyor. Gemi limana göre kaç km doğuya ilerlemiştir?', '20', ['20√2', '10√2', '40'], 'Doğu bileşeni 20√2·sin 45° = 20√2·(√2/2) = 20 km.'),
  ('tan x·cos x ifadesinin sadeleştirilmiş biçimi hangisidir?', 'sin x', ['cos²x', '1', 'cot x'], 'tan x = sin x/cos x olduğundan cos x\'ler sadeleşir ve sin x kalır.'),
  ('cos²x·(tan²x + 1) çarpımının değeri ne olur?', '1', ['sin²x', 'cos²x', 'tan²x'], 'tan²x + 1 = 1/cos²x olduğundan çarpım 1\'dir.'),
  ('sin x·csc x + cos x·sec x + tan x·cot x toplamının değeri hangisidir?', '3', ['1', '0', '6'], 'Her çarpım bir fonksiyonla tersinin çarpımı olduğundan 1\'e eşittir; toplam 3.'),
  ('cos 36° − cos 72° farkının değeri kaçtır?', '1/2', ['√5/4', '1/4', '(√5 − 1)/2'], 'cos 36° = (1 + √5)/4 ve cos 72° = (√5 − 1)/4 olduğundan fark 2/4 = 1/2.'),
  ('Bir üçgende tan A = 1 ve tan B = 2 ise tan C kaçtır?', '3', ['−3', '1/3', '−1/3'], 'tan C = −tan(A + B) = −(1 + 2)/(1 − 2) = 3.'),
  ('Bir binanın 2 km uzaktan görüldüğü açı 0,01 radyandır. Küçük açı yaklaşımıyla binanın yüksekliği yaklaşık kaç metredir?', '20', ['200', '2', '0,2'], 'tan θ ≈ θ olduğundan h ≈ 2000·0,01 = 20 m.'),
  ('Bir dönme dolapta kabinin yüksekliği h(t) = 22 − 20 cos(πt/15) metre (t dakika) ile veriliyor. Dolap bir tam turu kaç dakikada tamamlar?', '30', ['15', 'π/15', '60'], 'Periyot 2π/(π/15) = 30 dakikadır.'),
  ('h(t) = 22 − 20 cos(πt/15) modelinde kabin t = 5 dakikada yerden kaç metre yüksektedir?', '12', ['32', '2', '22 − 10√3'], 'cos(π/3) = 1/2 ⇒ h = 22 − 10 = 12 m.'),
  ('Alternatif akımda gerilim V(t) = 311 sin(100πt) volt ile veriliyor (t saniye). Akımın frekansı kaç hertzdir?', '50', ['100', '311', '100π'], 'Açısal frekans ω = 100π = 2πf ⇒ f = 50 Hz.'),
  ('Orijin ile kutupsal koordinatları (4, 10°) ve (6, 40°) olan noktaların oluşturduğu üçgenin alanı kaç birimkaredir?', '6', ['12', '6√3', '3'], 'Alan = (1/2)·4·6·sin 30° = 6 birimkare.'),
  ('"Trigonometri" sözcüğü hangi dildeki kelimelerden türetilmiştir ve ne anlama gelir?', 'Yunanca; üçgen ölçümü', ['Latince; açı hesabı', 'Arapça; gölge bilgisi', 'Sanskritçe; yay ölçümü'], 'Yunanca trigonon (üçgen) ve metron (ölçü) sözcüklerinden türemiştir.'),
  ('"Trigonometria" sözcüğünü 1595\'te yayımladığı kitabın adında ilk kez kullanan Alman matematikçi kimdir?', 'Bartholomaeus Pitiscus', ['Johannes Kepler', 'Gottfried Wilhelm Leibniz', 'Simon Stevin'], 'Pitiscus\'un 1595 tarihli eseri Trigonometria başlığını taşır ve terim bu yolla yerleşmiştir.'),
  ('Taban açısının tanjantı 4/3 olan ikizkenar üçgenin tabanı 18 cm ise tabana ait yüksekliği kaç cm\'dir?', '12', ['24', '13,5', '9'], 'Tabanın yarısı 9 cm; h = 9·tan α = 9·4/3 = 12 cm.'),
  ('cos 100° + cos 80° toplamını indirgeme formülüyle hesaplayınız.', '0', ['2 cos 80°', '1', 'cos 180°'], 'cos 100° = cos(180° − 80°) = −cos 80° olduğundan toplam sıfırdır.'),
  ('sin 160° = a ise cos 70° değeri a cinsinden nedir?', 'a', ['−a', '√(1 − a²)', '−√(1 − a²)'], 'sin 160° = sin 20° = a ve cos 70° = sin 20° olduğundan cos 70° = a.'),
  ('cos 40° = m olduğuna göre sin 230° ifadesi m cinsinden hangisidir?', '−m', ['m', '√(1 − m²)', '−√(1 − m²)'], 'sin 230° = sin(270° − 40°) = −cos 40° = −m.'),
  ('tan 10° = k olduğuna göre tan 280° değeri nedir?', '−1/k', ['k', '−k', '1/k + k'], 'tan 280° = tan(270° + 10°) = −cot 10° = −1/k.'),
  ('cot(3π/2 + x) ifadesi indirgenince hangi ifade elde edilir?', '−tan x', ['tan x', 'cot x', '−cot x'], '3π/2 + x IV. bölgededir; kotanjant orada negatiftir ve 3π/2 ile ad değişir: −tan x.'),
  ('30°, 45°, 60° ve 90° açılarının her birinin sinüsünün karesi alınıp sonuçlar toplanırsa ne elde edilir?', '5/2', ['2', '3', '9/4'], '1/4 + 1/2 + 3/4 + 1 = 5/2.'),
  ('Özel açı değerlerini yerine koyarak cos 30°·cot 60° + sin 60°·tan 30° işlemini sonuçlandırınız.', '1', ['1/2', '√3', '3/2'], '(√3/2)(1/√3) + (√3/2)(1/√3) = 1/2 + 1/2 = 1.'),
  ('Aşağıdaki özel açı değerlerinden hangisi rasyonel bir sayıdır?', 'cos 60°', ['sin 45°', 'tan 30°', 'cos 30°'], 'cos 60° = 1/2 rasyoneldir; diğerleri √2/2, √3/3 ve √3/2 olup irrasyoneldir.'),
  ('cos x = 0,6 ve x dördüncü bölgede ise tan x + cot x toplamı nedir?', '−25/12', ['25/12', '−7/12', '−25/144'], 'sin x = −0,8; tan x = −4/3, cot x = −3/4; toplam −25/12.'),
  ('tan x = 2 olduğuna göre (3 sin x + cos x)/(sin x + 2 cos x) oranı kaçtır?', '7/4', ['5/4', '7/3', '7/2 + 1'], 'Pay ve payda cos x\'e bölünürse (3·2 + 1)/(2 + 2) = 7/4.'),
  ('y = sin(x + π/4) eğrisi, y = sin x eğrisinin hangi ötelemesidir?', 'π/4 birim sola', ['π/4 birim sağa', 'π/4 birim yukarı', 'π/4 birim aşağı'], 'f(x + a) biçimi (a > 0) grafiği a birim sola kaydırır.'),
  ('y = cot x eğrisinin (0, π) aralığındaki davranışı nasıldır?', 'Sürekli azalır', ['Sürekli artar', 'Önce artar sonra azalır', 'Sabittir'], 'Kotanjant (0, π) aralığında +∞\'dan −∞\'a doğru kesin azalan bir fonksiyondur.'),
  ('sin(arccos(−1)) ifadesinin değeri kaçtır?', '0', ['−1', '1', 'π'], 'arccos(−1) = π ve sin π = 0.'),
  ('arccos(cos(−π/3)) ifadesinin değeri nedir?', 'π/3', ['−π/3', '2π/3', '5π/3'], 'cos(−π/3) = 1/2 ve arccos(1/2) = π/3; arccos negatif değer üretmez.'),
  ('sin(2·arctan 2) ifadesinin değeri kaçtır?', '4/5', ['2/5', '4/3', '3/5'], 'θ = arctan 2 için sin 2θ = 2tan θ/(1 + tan²θ) = 4/5.'),
  ('y = arcsin x fonksiyonu tanım kümesinde nasıl bir fonksiyondur?', 'Artandır', ['Azalandır', 'Çift fonksiyondur', 'Periyodiktir'], 'arcsin, [−π/2, π/2] aralığında artan olan sinüsün tersi olduğundan o da artandır.'),
  ('4sin²x = 3 eşitliğini sağlayan [0, 2π) aralığındaki açıların sayısı kaçtır?', '4', ['2', '3', '6'], 'sin x = ±√3/2 ⇒ π/3, 2π/3, 4π/3, 5π/3; dört çözüm.'),
  ('Katsayıları eşit olan √2 sin x + √2 cos x toplamını genlik ve faz açısı kullanarak yeniden yazınız.', '2 sin(x + π/4)', ['2 sin(x − π/4)', '√2 sin(x + π/4)', '4 sin(x + π/4)'], 'Genlik √(2 + 2) = 2; cos φ = sin φ = √2/2 ⇒ φ = π/4.'),
  ('Mutlak değer içeren y = 2 + |sin 3x| bağıntısında y\'nin alabileceği bütün değerler hangi aralıktadır?', '[2, 3]', ['[1, 3]', '[2, 5]', '[0, 3]'], '|sin 3x| ∈ [0, 1] olduğundan y ∈ [2, 3].'),
  ('Dakikada 600 tur atan bir motor milinin açısal hızı saniyede kaç radyandır?', '20π', ['10π', '600π', '60π'], '600 tur/dk = 10 tur/s; 10·2π = 20π rad/s.'),
  ('Bir açının radyan ölçüsünün birimsiz bir sayı olarak düşünülmesinin nedeni nedir?', 'Yay ile yarıçapın oranı olması', ['Derecenin 360\'a bölünmesi', 'π sayısının irrasyonel olması', 'Açıların her zaman pozitif olması'], 'θ = s/r ifadesinde pay ve payda aynı birimdedir; birimler sadeleşir.'),
  ('Ankara\'nın enlemi yaklaşık 39° 56′ olarak verilir. Bu değer ondalık derece olarak yaklaşık kaçtır?', '39,93°', ['39,56°', '39,96°', '39,056°'], '56′ = 56/60 ≈ 0,933°; toplam ≈ 39,93°.'),
  ('Gökbilimde bir yıldızın paralaks açısı 0,5 yay saniyesi (0,5″) ölçülmüştür. Bu açı kaç derecedir?', '1/7200', ['1/120', '1/3600', '1/72 000'], '1° = 3600″ olduğundan 0,5″ = 0,5/3600 = 1/7200 derece.'),
  ('Yatayla 30° açı yapan 20 N büyüklüğündeki bir kuvvetin yatay bileşeni kaç N\'dur?', '10√3', ['10', '20√3', '10√3/3'], 'Yatay bileşen F·cos 30° = 20·(√3/2) = 10√3 N.'),
  ('Hızı 50 m/s olan bir top yatayla 53° açıyla atılıyor (sin 53° = 0,8). İlk hızın düşey bileşeni kaç m/s\'dir?', '40', ['30', '50', '62,5'], 'Düşey bileşen v·sin 53° = 50·0,8 = 40 m/s.'),
  ('cos²22,5° − sin²22,5° farkı hangi değere eşittir?', '√2/2', ['1/2', '√3/2', '1 − √2/2'], 'İki kat açı formülüyle ifade cos 45° = √2/2 olur.'),
  ('sin x·cos x·cos 2x ifadesi hangi tek terime eşittir?', '(1/4)·sin 4x', ['(1/2)·sin 4x', '(1/4)·sin 2x', 'sin 4x'], 'sin x cos x = (sin 2x)/2; (sin 2x cos 2x)/2 = (sin 4x)/4.'),
  ('sin(x + 30°) + sin(x − 30°) toplamı hangi ifadeye eşittir?', '√3·sin x', ['√3·sin x·cos x', '2 sin x', '√3·cos x'], 'Toplam 2 sin x cos 30° = √3 sin x olur.'),
  ('cos(60° + x) + cos(60° − x) toplamı hangi ifadeye eşittir?', 'cos x', ['2 cos x', '√3 cos x', 'sin x'], 'Toplam 2 cos 60° cos x = cos x olur.'),
  ('Periyodu 3 olan bir sinüs fonksiyonu y = sin(kx) biçiminde yazılırsa k > 0 kaçtır?', '2π/3', ['3', 'π/3', '3/(2π)'], '2π/k = 3 ⇒ k = 2π/3.'),
  ('csc x = 2 ve x ikinci bölgede ise sec x değeri kaçtır?', '−2/√3', ['2/√3', '−2', '−1/(2√3)'], 'sin x = 1/2 ⇒ x = 150°; cos x = −√3/2 ve sec x = −2/√3.'),
  ('y = csc x fonksiyonunun görüntü kümesi hangisidir?', '(−∞, −1] ∪ [1, ∞)', ['[−1, 1]', '(−1, 1)', 'Tüm gerçek sayılar'], 'sin x ∈ [−1, 1] ve sıfırdan farklı olduğunda tersi mutlak değerce en az 1 olur.'),
  ('Esas ölçüsü 45° olan negatif açıların en büyüğü kaç derecedir?', '−315°', ['−45°', '−405°', '−675°'], '45° − 360° = −315°; daha büyük negatif açı bu esas ölçüyü vermez.'),
  ('Bir pervane saniyede 7/4 tur atmaktadır. Başlangıçtan 1 saniye sonra bir kanadının yaptığı açının esas ölçüsü kaç derecedir?', '270°', ['90°', '630°', '157,5°'], '7/4 tur = 630°; 630 − 360 = 270°.'),
  ('arctan(tan(3π/4)) ifadesinin değeri neden 3π/4 değildir ve kaçtır?', '−π/4; arctan esas aralıkta değer verir', ['3π/4, çünkü işlemler birbirini götürür', 'π/4, çünkü tanjant pozitiftir', '−3π/4, çünkü işaret değişir'], 'tan(3π/4) = −1 ve arctan(−1) esas aralıkta −π/4\'tür.'),
  ('cos(2x − π/3) = 1 denkleminin genel çözümü hangisidir (k ∈ ℤ)?', 'x = π/6 + kπ', ['x = π/3 + kπ', 'x = π/6 + 2kπ', 'x = π/6 + kπ/2'], '2x − π/3 = 2kπ ⇒ x = π/6 + kπ.'),
  ('sin x + cos x = t olmak üzere sin x·cos x ifadesi t cinsinden hangisidir?', '(t² − 1)/2', ['(1 − t²)/2', 't² − 1', '(t² + 1)/2'], 't² = 1 + 2 sin x cos x ⇒ sin x cos x = (t² − 1)/2.'),
  ('(1 − cos 2x)/sin 2x oranı aşağıdakilerden hangisine eşittir?', 'tan x', ['cot x', 'sin x', 'tan 2x'], 'Pay 2sin²x, payda 2 sin x cos x; sadeleşince sin x/cos x = tan x.'),
  ('Sinüs ve kosinüs toplamının karesinden 1 çıkarılırsa geriye hangi iki kat açılı terim kalır?', 'sin 2x', ['cos 2x', '2 sin x', '0'], 'Açılım 1 + 2 sin x cos x − 1 = 2 sin x cos x = sin 2x.'),
  ('Bir şehirde gün uzunluğu G(n) = 12 + 3 sin(2π(n − 80)/365) saat ile modelleniyor. En uzun gün kaç saattir?', '15', ['12', '9', '13,5'], 'Sinüs en çok 1 olduğunda G = 12 + 3 = 15 saattir.'),
  ('Birim çemberde bir açının bitiş kenarı üzerindeki nokta (0,6; −0,8) ise açı hangi bölgededir ve sinüsü kaçtır?', 'IV. bölge; −0,8', ['IV. bölge; 0,6', 'II. bölge; −0,8', 'III. bölge; −0,6'], 'x > 0 ve y < 0 olduğundan IV. bölgededir; sinüs ordinata eşittir.'),
  ('cos 3x + cos x toplamı çarpım biçiminde nasıl yazılır?', '2 cos 2x·cos x', ['2 sin 2x·sin x', '2 cos 2x·sin x', '2 cos 4x·cos 2x·cos x'], 'cos a + cos b = 2 cos((a + b)/2) cos((a − b)/2) = 2 cos 2x cos x.'),
  ('2 sin 3x·cos x ifadesi toplam biçiminde hangisidir?', 'sin 4x + sin 2x', ['sin 4x − sin 2x', 'cos 4x + cos 2x', '2 sin 4x + 2 sin 2x'], '2 sin a cos b = sin(a + b) + sin(a − b) = sin 4x + sin 2x.'),
  ('2 cos 50°·cos 10° − cos 40° işleminin sonucu nedir?', '1/2', ['0', '√3/2', 'cos 20°'], '2 cos 50 cos 10 = cos 60° + cos 40°; cos 40° çıkarılınca 1/2 kalır.'),
  ('Bir dağcı, zirveye olan yatay uzaklığı 3 km iken zirveyi 10°\'lik yükselme açısıyla görüyor. tan 10° ≈ 0,176 alınırsa zirve dağcının bulunduğu yerden yaklaşık kaç metre yüksektedir?', '528', ['176', '1760', '300'], 'h = 3000·0,176 ≈ 528 m.'),
  ('Bir cisim sürtünmeli eğik düzlemde, eğim açısı θ iken kaymaya başlamaktadır. Statik sürtünme katsayısı μ = √3/3 ise θ kaç derecedir? (Kayma eşiğinde tan θ = μ)', '30°', ['60°', '45°', '37,5°'], 'tan θ = √3/3 ⇒ θ = 30°.'),
  ('y(t) = 3 sin(4πt) ile tanımlı bir titreşimin frekansı kaç hertzdir (t saniye)?', '2', ['4', '4π', '1/2'], 'ω = 4π = 2πf ⇒ f = 2 Hz; yani saniyede iki tam titreşim olur.'),
  ('(2, 0) noktası orijin etrafında pozitif yönde 60° döndürülürse hangi noktaya gelir?', '(1, √3)', ['(√3, 1)', '(1, −√3)', '(2, √3)'], 'Yeni nokta (2 cos 60°, 2 sin 60°) = (1, √3) olur.'),
  ('ABC üçgeninde a = b·cos C + c·cos B eşitliğine ne ad verilir?', 'İzdüşüm teoremi', ['Sinüs teoremi', 'Tanjant teoremi', 'Menelaos teoremi'], 'a kenarı, b ve c kenarlarının a üzerindeki dik izdüşümlerinin toplamıdır.'),
  ('Bütün açıları 60° olan bir üçgende açıların kosinüsleri toplandığında hangi sonuç çıkar?', '3/2', ['3√3/2', '1', '√3'], 'Her açı 60° olduğundan toplam 3·(1/2) = 3/2\'dir.'),
  ('Her x ∈ [−1, 1] için arccos(−x) ifadesi hangisine eşittir?', 'π − arccos x', ['−arccos x', 'arccos x', 'π/2 − arccos x'], 'cos(π − θ) = −cos θ olduğundan ve π − θ ∈ [0, π] kaldığından arccos(−x) = π − arccos x.'),
  ('cos(2·arcsin x) ifadesi x cinsinden hangisidir?', '1 − 2x²', ['2x² − 1', '2x√(1 − x²)', '1 − x²'], 'θ = arcsin x için cos 2θ = 1 − 2sin²θ = 1 − 2x².'),
  ('f(x) = arccos(2x − 1) fonksiyonunun tanım kümesi hangisidir?', '[0, 1]', ['[−1, 1]', '[0, 2]', '[−1/2, 1/2]'], '−1 ≤ 2x − 1 ≤ 1 ⇒ 0 ≤ 2x ≤ 2 ⇒ 0 ≤ x ≤ 1.'),
  ('y = cos(2x − π/2) eğrisi y = cos 2x eğrisinden nasıl elde edilir?', 'π/4 birim sağa', ['π/2 birim sağa', 'π/4 birim sola', 'π/2 birim sola'], 'cos(2x − π/2) = cos(2(x − π/4)) olduğundan öteleme π/4 birim sağadır.'),
  ('Üç katının sinüsü 1 olan açılar, 0 dahil 2π hariç aralıkta kaç tanedir?', '3', ['1', '6', '3/2'], '3x = π/2 + 2kπ ⇒ x = π/6, 5π/6, 3π/2; üç çözüm.'),
  ('tan x > √3 eşitsizliğinin (0, π/2) aralığındaki çözümü hangisidir?', '(π/3, π/2)', ['(π/6, π/2)', '(0, π/3)', '(π/3, 2π/3)'], 'Tanjant bu aralıkta artandır ve tan(π/3) = √3\'tür.'),
  ('tan(45° + 30°) açılımından yararlanılırsa tan 75° kaça eşit olur?', '2 + √3', ['2 − √3', '√3 + 1', '(√3 + 1)/2'], 'tan 75° = (1 + √3/3)/(1 − √3/3) = (3 + √3)/(3 − √3) = 2 + √3.'),
  ('tan(θ/2) = (1 − cos θ)/sin θ bağıntısıyla θ = 45° alınırsa tan 22,5° kaç bulunur?', '√2 − 1', ['√2 + 1', '2 − √2', '(√2 − 1)/2'], 'tan 22,5° = (1 − √2/2)/(√2/2) = (2 − √2)/√2 = √2 − 1.'),
];
